<?php
declare(strict_types=1);
function gc_staff_role(array $actor):string {if(!(bool)($actor['is_staff']??false))throw new ApiError('Недостаточно прав',403);return one('SELECT role FROM pg_staff_roles WHERE client_id=?',[$actor['id']])['role']??((int)$actor['id']===1000?'admin':'support');}
function gc_admin_guard(string $route,string $method,array $actor):void {
 $role=gc_staff_role($actor);
 gc_staff_session_required($actor);
 if($route==='reauth/')return;
 if($method==='GET'){
  if(in_array($route,['merchant-settings/','settings/','staff/','signature/'],true)&&$role!=='admin')throw new ApiError('Нужны права администратора',403);
  return;
 }
 $permissions=[
  'support'=>['note/','case-save/','enquiry-update/','evidence-upload/'],
  'operator'=>['note/','case-save/','enquiry-update/','client-create/','order-create/','payment-record/','payment-assign/','bank-confirm/','bank-import/','card-issue/','issue-reconcile/','retry-safe-command/','supplier-save/','program-save/','document-reject/','documents-prepare/','evidence-upload/'],
  'finance'=>['note/','case-save/','enquiry-update/','payment-record/','payment-assign/','bank-confirm/','bank-import/','settlement-prepare/','settlement-bank-credit/','settlement-event/','balance-reconcile/','refund-cancel-code/','refund-paid/','refund-resolve/','refund-recovery/','cancel-reconcile/','issue-reconcile/','retry-safe-command/','evidence-upload/','settlement-request-review/']
 ];
 if($role!=='admin'&&!in_array($route,$permissions[$role]??[],true))throw new ApiError('Для этого действия недостаточно полномочий',403);
 if($route!=='reauth/'&&PHP_SAPI!=='cli'&&(int)($_SESSION['gift_staff_reauth']??0)<time())throw new ApiError('Подтвердите пароль сотрудника для выполнения действий',428);
}
function gc_admin_note(array $actor,string $kind,string $ref,string $body):void {query('INSERT INTO pg_admin_notes(id,object_kind,object_ref,body,actor_id,created_at) VALUES(?,?,?,?,?,?)',[gc_uuid(),$kind,$ref,$body,$actor['id'],now()]);}
function gc_admin_mail(string $email,string $subject,string $body):void {query('INSERT INTO pm_mail_queue(recipient,subject,body,available_at,created_at) VALUES(?,?,?,?,?)',[$email,$subject,$body,now(),now()]);}
function gc_setting_save(string $name,mixed $value,array $actor):void {query('INSERT INTO pg_runtime_settings(name,value_json,updated_by,updated_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE value_json=VALUES(value_json),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)',[$name,json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$actor['id'],now()]);}
function gc_date(string $value):string {if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$value,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new ApiError('Проверьте дату YYYY-MM-DD');return $value;}
function gc_settlement_expected(array $s):int {return (int)$s['net_minor']+(int)one("SELECT COALESCE(SUM(amount_minor),0) n FROM pg_settlement_events WHERE settlement_id=? AND kind='adjustment'",[$s['id']])['n'];}
function gc_admin_user(string $email):array {
 $email=strtolower($email);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new ApiError('Проверьте email');
 $c=one('SELECT * FROM pm_clients WHERE email=?',[$email]);if($c)return $c;
 $id=allocate('client');query('INSERT INTO pm_clients(id,email,password_hash,password_prompt,created_at) VALUES(?,?,?,0,?)',[$id,$email,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),now()]);query('INSERT INTO pg_profiles(client_id,created_at) VALUES(?,?)',[$id,now()]);return one('SELECT * FROM pm_clients WHERE id=?',[$id]);
}
function gc_admin_checklist():array {
 require_once __DIR__.'/giftcards-documents.php';$g=gc_settings();$p=gc_credentials('pina');$signature=null;try{$signature=gc_signature_config();}catch(Throwable){}
 return ['pina'=>!empty($p['api_key'])&&!empty($p['site_id'])&&!empty($p['merchant_id']),'signature'=>$signature!==null,'legal'=>gc_legal_sales_ready(),'supplier'=>count(gc_catalog())>0,'sales'=>(bool)($g['sales_enabled']??false)];
}
